{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Cyclandelate, a lipophilic ester with a cyclohexyl group and a high transfer score (0.95), showed extremely low oral bioavailability in humans, supporting low F for the similarly lipophilic ester/acetal corticosteroid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Oxybutynin, an ester-containing drug with extensive first-pass metabolism, had absolute oral bioavailability of 6.2% in healthy volunteers, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Withaferin A, a steroidal natural product, showed poor oral bioavailability in humans, directly supporting low F for the steroid-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "AKBA, a lipophilic triterpenoid, had poor oral bioavailability due to low absorption and/or extensive metabolism, consistent with the query's high lipophilicity and ester/acetal prodrug character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Estradiol, a steroid, had oral bioavailability of only 4% in postmenopausal women, indicating that steroid scaffolds with high first-pass metabolism can have very low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Paclitaxel, a complex lipophilic natural product, has poor oral bioavailability attributed to CYP3A4 metabolism and P-gp efflux, analogous to likely barriers for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "β-Sitosterol, a sterol, had absolute oral bioavailability of 0.41% in volunteers, showing that highly lipophilic steroidal molecules can have extremely low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Perindopril, the highest-transfer analogue (0.97), is an ester prodrug; its active metabolite oral availability was 19% in young healthy subjects, just below the 20% threshold, so it does not affirm high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "In cirrhotic patients, perindoprilat availability after oral perindopril was 30%, a value above the 20% threshold; however, this is a single diseased-population estimate and is outweighed by the many low-bioavailability analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic steroidal ester/acetal prodrug (ciclesonide-like). Multiple high-transfer analogues—lipophilic esters, steroids, and complex natural products—show absolute oral bioavailability well below 20% (0.4–19%), driven by poor solubility, first-pass metabolism, and efflux. The only borderline high value (perindopril 30% in cirrhotic patients) is a single diseased-population estimate and is outweighed. Prediction: low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for ciclesonide itself in the provided evidence; extrapolation relies on analogues.",
    "Perindopril evidence is borderline and from a different chemical class; direct human oral PK for ciclesonide would reduce uncertainty.",
    "Formulation and prodrug activation differences are not fully captured by the analogue evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

